def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if n == 4 or n == 8 or n == 12:
        return 'D'

    if n < 15:
        return 'C'

    my_defects = 0
    opp_defects = 0
    retaliations = 0
    followed = 0
    for i, (me, opp) in enumerate(history):
        if me == 'D':
            my_defects += 1
            if i + 1 < n:
                followed += 1
                if history[i+1][1] == 'D':
                    retaliations += 1
        if opp == 'D':
            opp_defects += 1

    if followed > 0:
        ret_rate = retaliations / followed
    else:
        ret_rate = 0.5

    last_opp = history[-1][1]
    last_me = history[-1][0]

    if opp_defects <= 2 and n > 20:
        return 'D'

    if opp_defects * 2 > n:
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            return 'C'
        if opp_defects <= 3 and n > 20:
            return 'C'
        return 'D'
    else:
        if last_me == 'D':
            return 'C'

        since_def = 0
        for h in reversed(history):
            if h[0] == 'D':
                break
            since_def += 1

        if ret_rate < 0.2:
            interval = 2
        elif ret_rate < 0.4:
            interval = 4
        elif ret_rate < 0.6:
            interval = 8
        elif ret_rate < 0.8:
            interval = 12
        else:
            interval = 20

        if n > 80 and opp_defects <= 5:
            if interval > 4:
                interval = 4

        if since_def >= interval:
            return 'D'
        return 'C'
